#include <stdio.h>
#include <stdlib.h>
#define SIZE 5
int head = 0;
int count = 0;
long items[SIZE];

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("NOOP\n");
        return 0;
    }
    for (int i = 1; i < argc; i++) {
        char *arg = argv[i];
        if (arg[0] == 'E') {
            long value = strtol(arg + 1, NULL, 10);
            if (count < SIZE) {
                items[(head + count) % SIZE] = value;
                count++;
                printf("ENQ %ld\n", value);
            } else {
                printf("FULL\n");
            }
        } else if (arg[0] == 'D') {
            if (count > 0) {
                long value = items[head];
                head = (head + 1) % SIZE;
                count--;
                printf("DEQ %ld\n", value);
            } else {
                printf("EMPTY\n");
            }
        } else if (arg[0] == 'F') {
            if (count > 0) {
                printf("FRONT %ld\n", items[head]);
            } else {
                printf("EMPTY\n");
            }
        } else {
            printf("ERR\n");
        }
    }
    return 0;
}
